"""Topic-specific Insights field guides; prose remains in content/blog/*.md."""
from pathlib import Path
from datetime import datetime
from functools import lru_cache
import json
import re
import html
from site_chrome import HEADER, FOOTER, FONTS, SOCIAL

ROOT=Path(__file__).resolve().parent.parent
@lru_cache(maxsize=1)
def registry():
    return json.loads((ROOT/'content/insight-guides.json').read_text())

def guide_for(slug):
    return registry().get(slug)

def esc(value):
    return html.escape(str(value),quote=True)

def cost_lab():
    return '''<div class="cost-lab"><div class="cost-inputs"><label>Monthly tasks<input id="tasks" type="number" min="1" max="1000000" step="1" value="1000" inputmode="numeric"></label><label>AI processing per task (USD)<input id="ai-cost" type="number" min="0" max="1000" step="0.01" value="0.08" inputmode="decimal"></label><label>Human review per task (minutes)<input id="review-minutes" type="number" min="0" max="120" step="0.1" value="2" inputmode="decimal"></label><label>Loaded review cost per hour (USD)<input id="hourly-rate" type="number" min="0" max="1000" step="1" value="60" inputmode="decimal"></label><button class="reset-inputs" type="button" id="reset-cost">Reset example</button></div><div class="cost-result" aria-live="polite"><span class="mono">ILLUSTRATIVE MONTHLY COST</span><strong id="total-cost">$2,080.00</strong><p id="unit-cost">$2.08 per task</p><div class="cost-bar" aria-hidden="true"><span id="ai-bar" style="width:3.846%"></span><span id="review-bar" style="width:96.154%"></span></div><div class="cost-breakdown"><span>AI processing <b id="ai-total">$80.00</b></span><span>Human review <b id="review-total">$2,000.00</b></span></div><p id="cost-validation" class="small-note">Edit the inputs to explore the tradeoff.</p></div></div><p class="lab-note">Formula: tasks × [AI cost + (review minutes ÷ 60 × hourly cost)]. Illustrative assumptions in USD, not vendor prices or an ROI forecast. Excludes implementation, licenses, retrieval, monitoring, exceptions, and other costs. Saved time does not automatically become cash savings.</p>'''

def permission_lab():
    return '''<div class="permission-lab"><div class="permissions"><span class="mono">TOOL PERMISSIONS</span><label><input type="checkbox" checked disabled>Read approved queue <small>Required for this example</small></label><label><input type="checkbox" checked disabled>Prepare a summary <small>Required for this example</small></label><label><input type="checkbox" data-permission="send">Send customer email</label><label><input type="checkbox" data-permission="modify">Modify customer records</label><label><input type="checkbox" data-permission="delete">Delete messages</label></div><div class="permission-result" aria-live="polite"><span class="mono">REACHABLE ACTIONS</span><h3 id="permission-title">Read and prepare.</h3><p id="permission-description">The example is limited to reading the approved queue and preparing a summary. A person takes the next consequential action.</p><ul id="action-list"><li>Read the approved queue</li><li>Prepare a summary</li></ul><p class="small-note">This shows the actions granted by the selected tools. It does not calculate risk or validate an implementation.</p></div></div>'''

def explorer_lab(g):
    buttons=''.join(f'<button type="button" data-step="{i}" aria-pressed="{str(i==0).lower()}" aria-controls="explorer-panel"><span>{i+1:02}</span>{esc(s["label"])}</button>' for i,s in enumerate(g['steps']))
    s=g['steps'][0]
    return f'''<div class="explorer-controls" role="group" aria-label="Explore the decision stages">{buttons}</div><div class="explorer-panel" id="explorer-panel" aria-live="polite"><div class="explorer-symbol" aria-hidden="true"><span id="step-number">01</span><div class="orbit"></div></div><div><p class="eyebrow" id="step-label">{esc(s['label'])}</p><h3 id="step-title">{esc(s['title'])}</h3><p id="step-text">{esc(s['text'])}</p><dl><div><dt>Accountable role</dt><dd id="step-owner">{esc(s['owner'])}</dd></div><div><dt>Bring to the review</dt><dd id="step-evidence">{esc(s['evidence'])}</dd></div></dl></div></div>'''

def art(g,slug):
    kind='rings' if g['kind']=='permissions' else 'stack' if ('supply-chain' in slug or 'control-plane' in slug or 'vendor-pitch' in slug) else 'path'
    nodes=''.join(f'<div class="art-node"><span>{i:02}</span><b>{esc(label)}</b><i aria-hidden="true">↗</i></div>' for i,label in enumerate(g['art'][1:],1))
    return f'''<figure class="insight-art art-{kind}" aria-label="Concept diagram: {esc(', '.join(g['art'][1:]))}"><div class="art-grid" aria-hidden="true"></div><div class="art-orbits" aria-hidden="true"><i></i><i></i><i></i></div><div class="art-nodes">{nodes}</div><figcaption><span class="signal-dot" aria-hidden="true"></span>{esc(g['art'][0])}</figcaption></figure>'''

def render_insight(fields,body,g):
    parts=re.split(r'<h2>(.*?)</h2>',body,flags=re.S)
    if len(parts)<3:raise ValueError('Field guide requires article sections: '+fields['slug'])
    intro=parts[0]; sections=list(zip(parts[1::2],parts[2::2]));slug=fields['slug']
    rail=''.join(f'<a href="#chapter-{i}"><span>{i:02}</span>{title}</a>' for i,(title,_) in enumerate(sections,1))
    chapters=''.join(f'<section class="insight-chapter" id="chapter-{i}"><div class="chapter-heading"><span>{i:02}</span><h2>{title}</h2></div>{text}</section>' for i,(title,text) in enumerate(sections,1))
    questions=''.join(f'<label class="worksheet-question"><input type="checkbox" data-question="{i}"><span><small>QUESTION {i+1:02}</small>{esc(q)}</span><i aria-hidden="true">＋</i></label>' for i,q in enumerate(g['questions']))
    sources=''.join(f'<li><a href="{esc(s["url"])}">{esc(s["title"])} <span aria-hidden="true">↗</span></a></li>' for s in g['sources'])
    lab=cost_lab() if g['kind']=='cost' else permission_lab() if g['kind']=='permissions' else explorer_lab(g)
    data=json.dumps(dict(slug=slug,title=fields['title'],steps=g['steps'],questions=g['questions']),ensure_ascii=False).replace('</','<\\/')
    updated=datetime.strptime(fields.get('updated',fields['date']),'%Y-%m-%d').strftime('%B %d, %Y').replace(' 0',' ')
    words=len(re.sub('<[^>]+>',' ',body).split());minutes=max(3,round(words/180))
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(fields['title'])} — Alphaworx Insights</title><meta name="description" content="{esc(fields['excerpt'])}"><link rel="canonical" href="https://alphaworx.io/blog/{slug}.html"><link rel="icon" href="/assets/mark.png">{FONTS}{SOCIAL}<link rel="stylesheet" href="/assets/editorial.css?v=review-1"><link rel="stylesheet" href="/assets/insight-guides.css?v=1"></head><body class="insight-guide">{HEADER}<div class="guide-progress" aria-hidden="true"><span id="guide-progress"></span></div><main id="main"><section class="insight-hero guide-shell"><div><a class="back-insights" href="/blog/">← All insights</a><p class="eyebrow line">{esc(fields['category'])} / EXECUTIVE FIELD GUIDE</p><h1>{esc(fields['title'])}</h1><p class="hero-dek">{esc(fields['excerpt'])}</p><div class="insight-meta"><span>Alphaworx Insights</span><span>Updated {updated}</span><span>{minutes} min read + explorer</span></div><div class="insight-actions"><a href="#decision-lab" class="guide-primary">Explore the decision ↗</a><a href="#article" class="guide-text-link">Read the article ↓</a></div></div>{art(g,slug)}</section><div class="guide-thesis guide-shell"><span class="eyebrow">THE LEADERSHIP QUESTION</span><p>{esc(g['quote'])}</p></div><section class="decision-lab guide-shell" id="decision-lab"><div class="lab-heading"><div><p class="eyebrow line">PUT THE IDEA TO WORK</p><h2>{esc(g['lab'][0])}</h2></div><p>{esc(g['lab'][1])}</p></div><div class="lab-board"><div class="lab-meta"><span>MERIDIAN INDUSTRIAL GROUP</span><span>{'Dated orientation · not a compliance determination' if 'ai-act' in slug else 'Fictional company · illustrative exercise'}</span></div>{lab}</div></section><div class="article-layout guide-shell" id="article"><aside class="insight-rail"><p class="eyebrow">IN THIS ARTICLE</p><nav aria-label="Article chapters">{rail}<a href="#worksheet"><span>↗</span>Your discussion notes</a><a href="#sources"><span>↗</span>Sources</a></nav></aside><article class="insight-body"><div class="article-intro">{intro}</div>{chapters}</article></div><section class="worksheet-section" id="worksheet"><div class="guide-shell worksheet-layout"><div><p class="eyebrow line">TAKE IT TO YOUR TEAM</p><h2>Turn the reading<br>into a conversation.</h2><p>Select the questions you want to bring to a working session. Your choices stay in this page and reset when you reload.</p><p class="small-note">These are discussion prompts, not a scored assessment.</p><button type="button" class="reset-inputs" id="clear-questions">Clear selections</button></div><div><div class="worksheet-questions">{questions}</div><div class="worksheet-export"><span id="question-count" aria-live="polite">0 questions selected</span><button type="button" id="download-notes" disabled class="guide-primary">Download notes ↓</button><button type="button" id="print-notes" disabled class="guide-text-button">Print ↗</button></div><p class="small-note" id="export-status" aria-live="polite"></p><div class="print-questions" id="print-questions"></div></div></div></section><section class="guide-sources guide-shell" id="sources"><div><p class="eyebrow line">EVIDENCE & FURTHER READING</p><h2>Follow the sources.</h2><p>Primary sources checked September 5, 2026. Scenarios, questions, and operating recommendations are Alphaworx’s own; vendor terms and legal requirements can change.</p></div><ul>{sources}</ul></section><section class="guide-next guide-shell"><div><p class="eyebrow">MAKE THE NEXT DECISION CLEARER</p><h2>Bring your context.<br>We’ll work through the decision.</h2></div><div><a class="guide-primary" href="/#contact">Start a conversation ↗</a><a class="guide-text-link" href="/blog/twelve-first-principles-enterprise-ai.html">Explore the twelve principles →</a></div></section></main><div class="guide-shell motion-row"><button type="button" id="guide-motion" aria-pressed="false">Pause motion</button></div>{FOOTER}<script type="application/json" id="insight-data">{data}</script><script src="/assets/insight-guides.js?v=1" defer></script></body></html>'''
